class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can(s, idx, target):
            if idx == len(s):
                return target == 0
            if target < 0:
                return False
            val = 0
            for j in range(idx, len(s)):
                val = val * 10 + int(s[j])
                if val > target:
                    break
                if can(s, j + 1, target - val):
                    return True
            return False

        total = 0
        for i in range(1, n + 1):
            sq = i * i
            if can(str(sq), 0, i):
                total += sq
        return total
