from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best = 0
        present = set(nums)
        for v in present:
            if v == k:
                continue
            cur = 0
            mx = 0
            for a in nums:
                if a == v:
                    cur += 1
                    if cur > mx:
                        mx = cur
                elif a == k:
                    cur -= 1
                    if cur < 0:
                        cur = 0
            if mx > best:
                best = mx
        return base + best
