class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def subs(x):
            st = set([""])
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    st.add(x[i:j])
            return sorted(st, key=len, reverse=True)
        A = subs(s)
        B = subs(t)
        best = 0
        for a in A:
            la = len(a)
            if la + len(B[0]) <= best:
                break
            for b in B:
                L = la + len(b)
                if L <= best:
                    break
                c = a + b
                if c == c[::-1]:
                    best = L
                    break
        return best
```

